{"packet_id":"R003-01","doc_id":"R003","jurisdiction":"Newark, NJ","category":"security_deposits","lifecycle":"enacted","title":"Newark security deposit limit","requirement":"A landlord may not demand or accept a security deposit of more than 1.5 times the monthly rent for a residential rental unit; after a rent increase a landlord may require an additional deposit only up to 1.5 times the new rent.","key_value":"1.5 times monthly rent","coverage_conditions":"Residential rental units in Newark; does not apply to owner-occupied buildings with two or fewer rental units.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":true,"other":"Exempts owner-occupied buildings with two or fewer rental units"},"exemptions":"Owner-occupied buildings with two or fewer rental units.","penalty":null,"effective_date":"2026-09-09","citation":"Newark Ordinance 6PSF-A § 1","quoted_span":"(a) A landlord shall not demand or accept a security deposit of more than one and one-half (1.5) times the monthly rent for a residential rental unit.","interaction":null,"confidence":0.95,"conflict_flag":false,"conflict_note":null}
{"packet_id":"R003-01","doc_id":"R003","jurisdiction":"Newark, NJ","category":"security_deposits","lifecycle":"enacted","title":"Newark security deposit interest requirement","requirement":"The landlord must hold the security deposit in an interest-bearing account at a New Jersey bank and pay the tenant the interest earned each year.","key_value":"interest paid annually","coverage_conditions":"Residential rental units in Newark; does not apply to owner-occupied buildings with two or fewer rental units.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":true,"other":"Exempts owner-occupied buildings with two or fewer rental units"},"exemptions":"Owner-occupied buildings with two or fewer rental units.","penalty":null,"effective_date":"2026-09-09","citation":"Newark Ordinance 6PSF-A § 2","quoted_span":"The landlord shall hold the deposit in an interest-bearing account at a New Jersey bank and shall pay the tenant the interest earned each year.","interaction":null,"confidence":0.95,"conflict_flag":false,"conflict_note":null}
{"packet_id":"R003-01","doc_id":"R003","jurisdiction":"Newark, NJ","category":"security_deposits","lifecycle":"enacted","title":"Newark security deposit return deadline","requirement":"Within 30 days after the tenancy ends, the landlord must return the deposit with interest and an itemized statement of any deductions.","key_value":"30 days","coverage_conditions":"Residential rental units in Newark; does not apply to owner-occupied buildings with two or fewer rental units.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":true,"other":"Exempts owner-occupied buildings with two or fewer rental units"},"exemptions":"Owner-occupied buildings with two or fewer rental units.","penalty":"A landlord who fails to return the deposit as required shall pay the tenant twice the amount wrongfully withheld, plus court costs.","effective_date":"2026-09-09","citation":"Newark Ordinance 6PSF-A § 3","quoted_span":"Within thirty (30) days after the tenancy ends, the landlord shall return the deposit with interest, together with an itemized statement of any deductions.","interaction":null,"confidence":0.95,"conflict_flag":false,"conflict_note":null}
